import{_ as l,a0 as i,w as d,s as m,I as o,x as t,a1 as n,A as a,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Alien 魔法：RPM 和 DEB 互转 | LCTT x X-CMD","titleTemplate":false,"description":"Alien 魔法：RPM 和 DEB 互转 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Alien 魔法：RPM 和 DEB 互转 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Alien 魔法：RPM 和 DEB 互转 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150827 How to Convert From RPM to DEB and DEB to RPM Package Using Alien","title":"Alien 魔法：RPM 和 DEB 互转","tag":"201508","desc":""},"relativePath":"201508/20150827 How to Convert From RPM to DEB and DEB to RPM Package Using Alien.md","filePath":"[post].md"}'),s={name:"201508/20150827 How to Convert From RPM to DEB and DEB to RPM Package Using Alien.md"};function u(c,e,g,w,P,b){const p=i("Link");return d(),m("div",null,[e[19]||(e[19]=o("h1",{id:"alien-魔法-rpm-和-deb-互转",tabindex:"-1"},[t("Alien 魔法：RPM 和 DEB 互转 "),o("a",{class:"header-anchor",href:"#alien-魔法-rpm-和-deb-互转","aria-label":"Permalink to “Alien 魔法：RPM 和 DEB 互转”"},"​")],-1)),o("p",null,[e[1]||(e[1]=t("正如我确信，你们一定知道Linux下的多种软件安装方式：使用发行版所提供的包管理系统（",-1)),n(p,{href:"http://www.tecmint.com/linux-package-management/"},{default:a(()=>[...e[0]||(e[0]=[t("aptitude，yum，或者zypper",-1)])]),_:1}),e[2]||(e[2]=t("，还可以举很多例子），从源码编译（尽管现在很少用了，但在Linux发展早期却是唯一可用的方法），或者使用各自的低级工具dpkg用于.deb，以及rpm用于.rpm，预编译包，如此这般。",-1))]),e[20]||(e[20]=r(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-RPM-to-DEB-and-DEB-to-RPM.png" alt="Convert RPM to DEB and DEB to RPM"></p><p><em>使用Alien将RPM转换成DEB以及将DEB转换成RPM</em></p><p>在本文中，我们将为你介绍alien，一个用于在各种不同的Linux包格式相互转换的工具，其最常见的用法是将.rpm转换成.deb（或者反过来）。</p><p>如果你需要某个特定类型的包，而你只能找到其它格式的包的时候，该工具迟早能派得上用场——即使是其作者不再维护，并且在其网站声明：alien将可能永远维持在实验状态。</p><p>例如，有一次，我正查找一个用于喷墨打印机的.deb驱动，但是却没有找到——生产厂家只提供.rpm包，这时候alien拯救了我。我安装了alien，将包进行转换，不久之后我就可以使用我的打印机了，没有任何问题。</p><p>即便如此，我们也必须澄清一下，这个工具不应当用来转换重要的系统文件和库，因为它们在不同的发行版中有不同的配置。只有在前面说的那种情况下所建议的安装方法根本不适合时，alien才能作为最后手段使用。</p><p>最后一项要点是，我们必须注意，虽然我们在本文中使用CentOS和Debian，除了前两个发行版及其各自的家族体系外，据我们所知，alien可以工作在Slackware中，甚至Solaris中。</p><h3 id="步骤1-安装alien及其依赖包" tabindex="-1">步骤1：安装Alien及其依赖包 <a class="header-anchor" href="#步骤1-安装alien及其依赖包" aria-label="Permalink to “步骤1：安装Alien及其依赖包”">​</a></h3><p>要安装alien到CentOS/RHEL 7中，你需要启用EPEL和Nux Dextop（是的，是Dextop——不是Desktop）仓库，顺序如下：</p><pre><code># yum install epel-release
</code></pre>`,10)),o("p",null,[e[4]||(e[4]=t("启用Nux Dextop仓库的包的当前最新版本是0.5（2015年8月10日发布），在安装之前你可以查看",-1)),n(p,{href:"http://li.nux.ro/download/nux/dextop/el7/x86_64/"},{default:a(()=>[...e[3]||(e[3]=[t("http://li.nux.ro/download/nux/dextop/el7/x86_64/",-1)])]),_:1}),e[5]||(e[5]=t("上是否有更新的版本。",-1))]),e[21]||(e[21]=r(`<pre><code># rpm --import http://li.nux.ro/download/nux/RPM-GPG-KEY-nux.ro
# rpm -Uvh http://li.nux.ro/download/nux/dextop/el7/x86_64/nux-dextop-release-0-5.el7.nux.noarch.rpm
</code></pre><p>然后再做，</p><pre><code># yum update &amp;&amp; yum install alien
</code></pre><p>在Fedora中，你只需要运行上面的命令即可。</p><p>在Debian及其衍生版中，只需要：</p><pre><code># aptitude install alien
</code></pre><h3 id="步骤2-将-deb转换成-rpm包" tabindex="-1">步骤2：将.deb转换成.rpm包 <a class="header-anchor" href="#步骤2-将-deb转换成-rpm包" aria-label="Permalink to “步骤2：将.deb转换成.rpm包”">​</a></h3><p>对于本次测试，我们选择了date工具，它提供了一系列日期和时间工具用于处理大量金融数据。我们将下载.deb包到我们的CentOS 7机器中，将它转换成.rpm并安装：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Check-Linux-OS-Version.png" alt="Check CentOS Version"></p><p>检查CentOS版本</p><pre><code># cat /etc/centos-release
# wget http://ftp.us.debian.org/debian/pool/main/d/dateutils/dateutils_0.3.1-1.1_amd64.deb
# alien --to-rpm --scripts dateutils_0.3.1-1.1_amd64.deb
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-deb-to-rpm-package.png" alt="Convert .deb to .rpm package in Linux"></p><p><em>在Linux中将.deb转换成.rpm</em></p><p><strong>重要</strong>：（请注意alien是怎样来增加目标包的次版本号的。如果你想要无视该行为，请添加-keep-version标识）。</p><p>如果我们尝试马上安装该包，我们将碰到些许问题：</p><pre><code># rpm -Uvh dateutils-0.3.1-2.1.x86_64.rpm 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-RPM-Package.png" alt="Install RPM Package"></p><p><em>安装RPM包</em></p><p>要解决该问题，我们需要启用epel-testing仓库，然后安装rpmbuild工具来编辑该包的配置以重建包：</p><pre><code># yum --enablerepo=epel-testing install rpmrebuild
</code></pre><p>然后运行，</p><pre><code># rpmrebuild -pe dateutils-0.3.1-2.1.x86_64.rpm
</code></pre><p>它会打开你的默认文本编辑器。请转到<code>%files</code>章节并删除涉及到错误信息中提到的目录的行，然后保存文件并退出：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-Deb-Package-to-Alien-Version.png" alt="Convert .deb to Alien Version"></p><p><em>转换.deb到Alien版</em></p><p>但你退出该文件后，将提示你继续去重构。如果你选择“Y”，该文件会重构到指定的目录（与当前工作目录不同）：</p><pre><code># rpmrebuild –pe dateutils-0.3.1-2.1.x86_64.rpm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Build-RPM-Package.png" alt="Build RPM Package"></p><p><em>构建RPM包</em></p><p>现在你可以像以往一样继续来安装包并验证：</p><pre><code># rpm -Uvh /root/rpmbuild/RPMS/x86_64/dateutils-0.3.1-2.1.x86_64.rpm
# rpm -qa | grep dateutils
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Build-RPM-Package.png" alt="Install Build RPM Package"></p><p><em>安装构建RPM包</em></p><p>最后，你可以列出date工具包含的各个工具，也可以查看各自的手册页：</p><pre><code># ls -l /usr/bin | grep dateutils
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Verify-Installed-Package.png" alt="Verify Installed RPM Package"></p><p><em>验证安装的RPM包</em></p><h3 id="步骤3-将-rpm转换成-deb包" tabindex="-1">步骤3：将.rpm转换成.deb包 <a class="header-anchor" href="#步骤3-将-rpm转换成-deb包" aria-label="Permalink to “步骤3：将.rpm转换成.deb包”">​</a></h3><p>在本节中，我们将演示如何将.rpm转换成.deb。在一台32位的Debian Wheezy机器中，让我们从CentOS 6操作系统仓库中下载用于zsh shell的.rpm包。注意，该shell在Debian及其衍生版的默认安装中是不可用的。</p><pre><code># cat /etc/shells
# lsb_release -a | tail -n 4
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Check-Shell-Debian-OS-Version.png" alt="Check Shell and Debian OS Version"></p><p><em>检查Shell和Debian操作系统版本</em></p><pre><code># wget http://mirror.centos.org/centos/6/os/i386/Packages/zsh-4.3.11-4.el6.centos.i686.rpm
# alien --to-deb --scripts zsh-4.3.11-4.el6.centos.i686.rpm
</code></pre><p>你可以安全地无视关于签名丢失的信息：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-rpm-to-deb-Package.png" alt="Convert .rpm to .deb Package"></p><p><em>将.rpm转换成.deb包</em></p><p>过了一会儿后，.deb包应该已经生成，并可以安装了：</p><pre><code># dpkg -i zsh_4.3.11-5_i386.deb
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Deb-Package.png" alt="Install RPM Converted Deb Package"></p><p><em>安装RPM转换来的Deb包</em></p><p>安装完后，你看看可以zsh是否添加到了合法shell列表中：</p><pre><code># cat /etc/shells
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Confirm-Installed-Package.png" alt="Confirm Installed Zsh Package"></p><p><em>确认安装的Zsh包</em></p><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3><p>在本文中，我们已经解释了如何将.rpm转换成.deb及其反向转换，这可以作为这类程序不能从仓库中或者作为可分发源代码获得的最后安装手段。你一定想要将本文添加到书签中，因为我们都需要alien。</p><p>请自由分享你关于本文的想法，写到下面的表单中吧。</p><hr>`,58)),o("p",null,[e[7]||(e[7]=t("via: ",-1)),n(p,{href:"http://www.tecmint.com/convert-from-rpm-to-deb-and-deb-to-rpm-package-using-alien/"},{default:a(()=>[...e[6]||(e[6]=[t("http://www.tecmint.com/convert-from-rpm-to-deb-and-deb-to-rpm-package-using-alien/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=t("作者：",-1)),n(p,{href:"http://www.tecmint.com/author/gacanepa/"},{default:a(()=>[...e[8]||(e[8]=[t("Gabriel Cánepa",-1)])]),_:1}),e[12]||(e[12]=t(" 译者：",-1)),n(p,{href:"https://github.com/GOLinux"},{default:a(()=>[...e[9]||(e[9]=[t("GOLinux",-1)])]),_:1}),e[13]||(e[13]=t(" 校对：",-1)),n(p,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=t("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原创翻译，",-1)),n(p,{href:"https://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[t("Linux中国",-1)])]),_:1}),e[18]||(e[18]=t(" 荣誉推出",-1))])])}const k=l(s,[["render",u]]);export{C as __pageData,k as default};
